    foreach (['permission', 'permission_response', 'usage_level'] as $k) {
        if (isset($_POST[$k]) && !in_array($_POST[$k], $bPerm, true)) beta_cmd_fail('Unknown permission level.');
    }
    if (isset($_POST['status']) && !in_array($_POST['status'], ['Enabled', 'Disabled'], true)) beta_cmd_fail('Status must be Enabled or Disabled.');
    foreach (['cooldown', 'cooldown_response'] as $k) {
        if (isset($_POST[$k]) && (!is_numeric($_POST[$k]) || (int) $_POST[$k] < 0 || (int) $_POST[$k] > 86400)) beta_cmd_fail('Cooldown must be a number of seconds.');
    }
    foreach (['response', 'command_response'] as $k) {
        if (isset($_POST[$k]) && mb_strlen((string) $_POST[$k]) > BETA_CMD_MAX) beta_cmd_fail('Response is longer than ' . BETA_CMD_MAX . ' characters.');
    }
}


