                $notification_status = "sp-alert-success";
            } else {
                $status = t('user_commands_msg_delete_not_found', ['command' => $command]);
                $notification_status = "sp-alert-danger";
            }
            $deleteSTMT->close();
        } catch (Exception $e) {
